import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip and move the compressed files to a destination folder.
    This operation runs as a background process.

    Parameters:
    src_folder (str): Path to the source folder containing files to compress.
    dst_folder (str): Path to the destination folder for compressed files.

    Returns:
    dict: A dictionary containing:
        'success': Boolean indicating if all files were processed successfully.
        'message': Descriptive message about the operation result.
        'failed_files': List of filenames that failed to compress or move.
    """

    # Validate input folders
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist.",
            'failed_files': []
        }

    # Create destination folder if it doesn't exist
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder, exist_ok=True)
        except Exception as e:
            return {
                'success': False,
                'message': f"Failed to create destination folder '{dst_folder}': {str(e)}",
                'failed_files': []
            }

    # Get all files in source folder (excluding subdirectories)
    try:
        files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    except Exception as e:
        return {
            'success': False,
            'message': f"Failed to list files in source folder: {str(e)}",
            'failed_files': []
        }

    if not files:
        return {
            'success': True,
            'message': f"No files found in source folder '{src_folder}'.",
            'failed_files': []
        }

    failed_files = []
    processed_count = 0

    for filename in files:
        src_file_path = os.path.join(src_folder, filename)
        compressed_filename = filename + '.gz'
        dst_file_path = os.path.join(dst_folder, compressed_filename)

        try:
            # Compress the file using gzip
            # Using subprocess.Popen to run in background
            process = subprocess.Popen(
                ['gzip', '-c', src_file_path],
                stdout=open(dst_file_path, 'wb'),
                stderr=subprocess.PIPE
            )

            # Wait for the process to complete
            stdout, stderr = process.communicate()

            if process.returncode != 0:
                failed_files.append(filename)
                # Clean up partially created file if it exists
                if os.path.exists(dst_file_path):
                    os.remove(dst_file_path)
            else:
                processed_count += 1

        except Exception as e:
            failed_files.append(filename)
            # Clean up partially created file if it exists
            if os.path.exists(dst_file_path):
                try:
                    os.remove(dst_file_path)
                except:
                    pass

    # Prepare result
    success = len(failed_files) == 0
    total_files = len(files)

    if success:
        message = f"Successfully compressed and moved {processed_count} file(s) from '{src_folder}' to '{dst_folder}'."
    else:
        message = f"Processed {processed_count} of {total_files} file(s). {len(failed_files)} file(s) failed."

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip and move the compressed files to a destination folder.
    This operation runs as a background process.

    Parameters:
    src_folder (str): The source folder containing files to compress.
    dst_folder (str): The destination folder for compressed files.

    Returns:
    dict: A dictionary containing:
        'success': Boolean indicating if all files were processed successfully.
        'message': Descriptive message about the operation.
        'failed_files': List of filenames that failed to process.
    """

    # Validate input folders
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist.",
            'failed_files': []
        }

    # Create destination folder if it doesn't exist
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder, exist_ok=True)
        except Exception as e:
            return {
                'success': False,
                'message': f"Failed to create destination folder '{dst_folder}': {str(e)}",
                'failed_files': []
            }

    # Get all files in source folder (excluding subdirectories)
    try:
        files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    except Exception as e:
        return {
            'success': False,
            'message': f"Failed to list files in source folder: {str(e)}",
            'failed_files': []
        }

    if not files:
        return {
            'success': True,
            'message': f"No files found in source folder '{src_folder}'.",
            'failed_files': []
        }

    failed_files = []
    processed_count = 0

    # Process each file
    for file_path in files:
        file_name = os.path.basename(file_path)
        compressed_file = file_path + '.gz'
        dst_file_path = os.path.join(dst_folder, file_name + '.gz')

        try:
            # Compress the file using gzip in background
            # Using subprocess.Popen to run in background
            process = subprocess.Popen(
                ['gzip', '-c', file_path],
                stdout=open(compressed_file, 'wb'),
                stderr=subprocess.PIPE
            )

            # Wait for compression to complete
            _, stderr = process.communicate()

            if process.returncode != 0:
                failed_files.append(file_name)
                # Clean up failed compression file if it exists
                if os.path.exists(compressed_file):
                    os.remove(compressed_file)
                continue

            # Move the compressed file to destination
            shutil.move(compressed_file, dst_file_path)
            processed_count += 1

        except Exception as e:
            failed_files.append(file_name)
            # Clean up any temporary compressed file
            if os.path.exists(compressed_file):
                try:
                    os.remove(compressed_file)
                except:
                    pass

    # Determine overall success
    success = len(failed_files) == 0

    # Create appropriate message
    if success:
        message = f"Successfully compressed and moved {processed_count} file(s) from '{src_folder}' to '{dst_folder}'."
    else:
        message = f"Processed {processed_count} file(s) successfully, {len(failed_files)} file(s) failed."

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip and move the compressed files to a destination folder.
    This operation runs as a background process.

    Parameters:
    src_folder (str): Path to the source folder containing files to compress.
    dst_folder (str): Path to the destination folder for compressed files.

    Returns:
    dict: A dictionary containing:
        'success': Boolean indicating if all files were compressed and moved successfully.
        'message': Descriptive message about the operation result.
        'failed_files': List of filenames that failed to compress or move.
    """

    # Validate input folders
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist.",
            'failed_files': []
        }

    # Create destination folder if it doesn't exist
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder, exist_ok=True)
        except Exception as e:
            return {
                'success': False,
                'message': f"Failed to create destination folder '{dst_folder}': {str(e)}",
                'failed_files': []
            }

    # Get all files in source folder (excluding subdirectories)
    try:
        files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    except Exception as e:
        return {
            'success': False,
            'message': f"Failed to list files in source folder: {str(e)}",
            'failed_files': []
        }

    if not files:
        return {
            'success': True,
            'message': f"No files found in source folder '{src_folder}'.",
            'failed_files': []
        }

    failed_files = []
    successful_files = []

    # Process each file
    for filename in files:
        src_file_path = os.path.join(src_folder, filename)
        compressed_filename = filename + '.gz'
        dst_file_path = os.path.join(dst_folder, compressed_filename)

        try:
            # Compress the file using gzip
            # Using subprocess.Popen to run in background
            with open(src_file_path, 'rb') as f_in:
                # Create gzip process
                gzip_process = subprocess.Popen(
                    ['gzip', '-c'],  # -c: write to stdout
                    stdin=f_in,
                    stdout=open(dst_file_path, 'wb'),
                    stderr=subprocess.PIPE
                )

                # Wait for the process to complete
                _, stderr = gzip_process.communicate()

                if gzip_process.returncode != 0:
                    raise Exception(f"gzip failed: {stderr.decode().strip()}")

                successful_files.append(filename)

        except Exception as e:
            failed_files.append(filename)
            # Clean up partially created compressed file if it exists
            if os.path.exists(dst_file_path):
                try:
                    os.remove(dst_file_path)
                except:
                    pass

    # Prepare result message
    if not failed_files:
        success = True
        message = f"Successfully compressed and moved {len(successful_files)} file(s) from '{src_folder}' to '{dst_folder}'."
    else:
        success = False
        if successful_files:
            message = f"Partially completed. {len(successful_files)} file(s) succeeded, {len(failed_files)} file(s) failed."
        else:
            message = f"Failed to compress and move any files. {len(failed_files)} file(s) failed."

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }
